mapper.select:
SELECT d.id, d.emp_no, d.user_nm, d.proj_code, d.proj_name, d.gw_code, d.mst_seq, d.rent_reason, d.rent_source, d.execution_budget, d.cust_reg_attempted, d.created_date, d.updated_date FROM draft d WHERE 1=1
AND d.emp_no = #{emp_no}
AND d.proj_code = #{proj_code}
ORDER BY d.created_date DESC

